import "server-only";
import data from "@/data/catalog.json";
import type { Card } from "./format";

/** Generated by scripts/catalog.py from the client's LIVESTA catalogue + livesta.ua. Server-only: the JSON is large. */
export type Product = {
  id: string;
  slug: string;
  name: string;
  vol: string | null;
  series: string | null;
  price: number;
  old: number | null;
  bb: number | null;
  section: string;
  sub: string | null;
  page: number;
  desc: string[];
  more: Record<string, string[]>;
  src: string;
  imgs: number;
  cut: boolean;
};
export type Sub = { id: string; name: string; count: number };
export type Section = { id: string; name: string; lead: string; count: number; subs: Sub[] };
export type Series = { id: string; name: string; count: number };

export const products = data.products as Product[];
export const sections = data.sections as Section[];
export const seriesList = data.series as Series[];

const bySlug = new Map(products.map((p) => [p.slug, p]));
const byId = new Map(products.map((p) => [p.id, p]));
const seriesName = new Map(seriesList.map((s) => [s.id, s.name]));

export const getProduct = (slug: string) => bySlug.get(slug);
export const getById = (id: string) => byId.get(id);
export const getSection = (id: string) => sections.find((s) => s.id === id);
export const getSeries = (id: string) => seriesList.find((s) => s.id === id);
export const subName = (sec: string, sub: string | null) => (sub ? getSection(sec)?.subs.find((s) => s.id === sub)?.name : undefined);
export const discount = (p: Product) => (p.old && p.old > p.price ? Math.round((1 - p.price / p.old) * 100) : 0);

export function toCard(p: Product): Card {
  return {
    id: p.id,
    s: p.slug,
    n: p.name,
    v: p.vol,
    p: p.price,
    o: p.old,
    sr: p.series,
    srn: p.series ? (seriesName.get(p.series) ?? null) : null,
    sec: p.section,
    sub: p.sub,
    img: p.imgs > 0,
    cut: p.cut,
  };
}

/** Cards by id, in the given order; unknown ids are skipped. */
export const cards = (ids: string[]) => ids.map((id) => byId.get(id)).filter((p): p is Product => Boolean(p)).map(toCard);

/** Catalogue order (the client's brochure order) is the default "recommended" order. */
export const allCards = () => products.map(toCard);

/** Same series first, then same sub-category, then same section; close in price. */
export function related(p: Product, n = 8) {
  const score = (q: Product) => (q.series && q.series === p.series ? 3 : 0) + (q.sub && q.sub === p.sub ? 2 : 0) + (q.section === p.section ? 1 : 0) + (q.imgs ? 0.5 : 0);
  return products
    .filter((q) => q.id !== p.id)
    .map((q) => ({ q, s: score(q) - Math.abs(Math.log(q.price / p.price)) * 0.25 }))
    .filter((x) => x.s > 0.5)
    .sort((a, b) => b.s - a.s)
    .slice(0, n)
    .map((x) => toCard(x.q));
}

/** The best "Крута ціна" offers: biggest discount, with a photo, one per series so the rail stays varied. */
const BEAUTY = new Set(["oblychchia", "volossia", "tilo", "makiiazh", "parfumeriia"]);
const NOT_BEAUTY = /щітк|зубн|прочищ|плям|посуд|прання|освіжувач|дифузор/i;

export function bestDeals(n = 12, section?: string) {
  const seen = new Set<string>();
  return products
    .filter((p) => p.imgs && (section ? p.section === section : BEAUTY.has(p.section) && !NOT_BEAUTY.test(p.name)) && discount(p) >= 20)
    .sort((a, b) => discount(b) - discount(a) || a.page - b.page)
    .filter((p) => {
      const k = p.series ?? p.id;
      if (seen.has(k)) return false;
      seen.add(k);
      return true;
    })
    .slice(0, n)
    .map(toCard);
}
